<?php
namespace App\Http\Controllers;
use App\Models\{User,Apprentice,Programme,CohortForecast,CohortSnapshot};
use App\Support\{CohortInsights as I,CohortForecasts as F,LearningAccess,AccountLifecycle};
use Illuminate\Http\Request;
class CohortInsightsController extends Controller {
 private function allowed(Request $r):void {abort_unless(LearningAccess::manager($r->user())&&!AccountLifecycle::blocked($r->user()),403);}
 private function view(string $name,array $data){return response()->view('cohort-insights.'.$name,$data)->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 private function filters(Request $r):array {$this->allowed($r);$d=$r->validate(['from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d','programme'=>'nullable|integer|exists:programmes,id','tutor'=>'nullable|integer|exists:users,id','as_of'=>'prohibited']);return ['from'=>$d['from']??today()->subYears(4)->toDateString(),'to'=>$d['to']??today()->toDateString(),'programme'=>isset($d['programme'])?(int)$d['programme']:null,'tutor'=>isset($d['tutor'])?(int)$d['tutor']:null];}
 public function index(Request $r){$d=$this->filters($r);return $this->view('index',['report'=>I::report($r->user(),...array_values($d)),'filters'=>$d,'programmes'=>Programme::orderBy('name')->get(),'tutors'=>User::where('role','tutor')->orderBy('name')->get(),'snapshots'=>CohortSnapshot::orderByDesc('created_at')->limit(15)->get()]);}
 public function snapshot(Request $r){$d=$this->filters($r);$v=$r->validate(['source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','confirmed'=>'accepted']);$s=I::snapshot($r->user(),(int)$r->session()->get('auth_version'),$d['from'],$d['to'],$d['programme'],$d['tutor'],$v['source_hash']);return to_route('cohort-insights.snapshot',$s)->with('status','Immutable aggregate-only cohort snapshot saved.');}
 public function show(Request $r,CohortSnapshot $snapshot){$this->allowed($r);return $this->view('snapshot',['snapshot'=>$snapshot,'body'=>I::readSnapshot($snapshot)]);}
 public function download(Request $r,CohortSnapshot $snapshot){$this->allowed($r);return response()->json(I::readSnapshot($snapshot),200,['Content-Disposition'=>'attachment; filename="GTA-Cohort-'.$snapshot->id.'.json"','Cache-Control'=>'no-store, private','Referrer-Policy'=>'no-referrer']);}
 public function compare(Request $r){$this->allowed($r);$d=$r->validate(['earlier'=>'required|uuid|exists:cohort_snapshots,id','later'=>'required|uuid|exists:cohort_snapshots,id']);return $this->view('compare',['comparison'=>I::compare(CohortSnapshot::findOrFail($d['earlier']),CohortSnapshot::findOrFail($d['later']))]);}
 public function forecast(Request $r,Apprentice $apprentice){abort_unless(F::allowed($r->user(),$apprentice),403);return $this->view('forecast',['a'=>$apprentice,'source'=>F::source($apprentice),'forecast'=>CohortForecast::find($apprentice->id)]);}
 public function saveForecast(Request $r,Apprentice $apprentice){abort_unless(F::allowed($r->user(),$apprentice),403);$d=$r->validate(['version'=>'required|integer|min:0','source_hash'=>'required|regex:/^[a-f0-9]{64}$/D','target'=>'required|date_format:Y-m-d','review'=>'required|date_format:Y-m-d','basis'=>'required|in:'.implode(',',F::BASES),'reference'=>'required|string|max:2000','reason'=>'required|string|max:2000','confirmed'=>'accepted']);F::save($r->user(),(int)$r->session()->get('auth_version'),$apprentice,(int)$d['version'],$d['source_hash'],$d['target'],$d['review'],$d['basis'],$d['reference'],$d['reason']);return back()->with('status','Checked staff estimate recorded against the current source; it is not guaranteed achievement or approval of Gateway.');}
}
